// MongoDB data layer.
// Documents keep numeric ids (_id: 1, 2, 3…) generated by an atomic counter, so the API and the
// React app keep the same URLs and ids. Child records (fiche lines, request works and history,
// invoice lines) are embedded in their parent document: one atomic write, no multi-document
// transaction needed, which works on a standalone local server as well as on MongoDB Atlas.
const path = require('path');
const fs = require('fs');
const { MongoClient } = require('mongodb');

const DATA_DIR = path.resolve(path.join(__dirname, '..'), process.env.DATA_DIR || 'data');   // backups, uploads
fs.mkdirSync(DATA_DIR, { recursive: true });

const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://127.0.0.1:27017/labo_dentaire';

function dbNameFromUri(uri) {
  const m = /^mongodb(?:\+srv)?:\/\/[^/]+\/([^?]+)/.exec(uri);
  return m ? decodeURIComponent(m[1]) : null;
}
const DB_NAME = process.env.MONGODB_DB || dbNameFromUri(MONGODB_URI) || 'labo_dentaire';

let client = null;
let database = null;

// Hide the password when printing the address
const safeUri = (u = MONGODB_URI) => u.replace(/\/\/([^:/@]+):([^@]+)@/, '//$1:****@');

async function connect() {
  if (database) return database;
  client = new MongoClient(MONGODB_URI, { serverSelectionTimeoutMS: 8000, appName: 'labo-dentaire' });
  try {
    await client.connect();
    await client.db('admin').command({ ping: 1 });
  } catch (e) {
    client = null;
    const err = new Error(`Connexion à MongoDB impossible (${safeUri()}) : ${e.message}`);
    err.code = 'MONGO_CONNECT';
    throw err;
  }
  database = client.db(DB_NAME);
  await ensureIndexes();
  return database;
}

async function close() {
  if (client) await client.close();
  client = null; database = null;
}

function db() {
  if (!database) throw new Error('Base de données non connectée : appelez connect() au démarrage.');
  return database;
}
const col = (name) => db().collection(name);

const COLLECTIONS = ['users', 'doctors', 'carnets', 'designations', 'price_history', 'fiches', 'requests', 'invoices',
  'notifications', 'notification_deliveries', 'push_subscriptions', 'password_resets', 'settings', 'counters', 'audit_log'];

async function ensureIndexes() {
  const d = database;
  const ix = (c, spec, opts = {}) => d.collection(c).createIndex(spec, opts);
  await Promise.all([
    ix('users', { email_key: 1 }, { unique: true }),
    ix('doctors', { name_key: 1 }, { unique: true }),
    ix('doctors', { archived: 1, last_name: 1 }),
    ix('carnets', { doctor_id: 1 }, { unique: true }),          // one carnet per doctor
    ix('carnets', { numero: 1 }, { unique: true }),
    ix('designations', { name_key: 1 }, { unique: true }),
    ix('price_history', { designation_id: 1, _id: -1 }),
    ix('fiches', { numero: 1 }, { unique: true }),
    ix('fiches', { doctor_id: 1, date: -1 }),
    ix('fiches', { carnet_id: 1, date: -1 }),
    ix('fiches', { invoice_id: 1 }),
    ix('fiches', { request_id: 1 }),
    ix('requests', { numero: 1 }, { unique: true }),
    ix('requests', { deleted_at: 1, status: 1 }),
    ix('requests', { doctor_id: 1 }),
    ix('invoices', { numero: 1 }, { unique: true, partialFilterExpression: { numero: { $type: 'string' } } }),
    ix('invoices', { doctor_id: 1, period: -1 }),
    ix('invoices', { corrects_invoice_id: 1 }),
    ix('notifications', { user_id: 1, dedup_key: 1 }, { unique: true }),   // never twice the same reminder
    ix('notifications', { user_id: 1, read_at: 1, created_at: -1 }),
    ix('notifications', { dedup_key: 1, created_at: -1 }),
    ix('push_subscriptions', { endpoint: 1 }, { unique: true }),
    ix('push_subscriptions', { user_id: 1 }),
    ix('password_resets', { token_hash: 1 }, { unique: true }),
    ix('password_resets', { user_id: 1, used_at: 1 }),
  ]);
}

/* ---------- ids, sequences, helpers ---------- */

// Atomic counter: nextSeq('request-2026') -> 1, 2, 3…
async function nextSeq(key) {
  const r = await col('counters').findOneAndUpdate({ _id: key }, { $inc: { value: 1 } }, { upsert: true, returnDocument: 'after' });
  return (r && r.value !== undefined && r.value.value !== undefined ? r.value.value : r.value);
}
const nextId = (collection) => nextSeq(`id:${collection}`);

// Inserts a document with a new numeric id and returns it in API form ({ id, … })
async function insert(collection, doc) {
  const _id = await nextId(collection);
  const full = { _id, ...doc, created_at: doc.created_at || nowStamp() };
  await col(collection).insertOne(full);
  return out(full);
}

// { _id, … } -> { id, … }
function out(doc) {
  if (!doc) return doc;
  const { _id, ...rest } = doc;
  return { id: _id, ...rest };
}

// URL parameter -> numeric id (or null)
function toId(v) {
  const n = Number(v);
  return Number.isInteger(n) && n > 0 ? n : null;
}

const pad = (n) => String(n).padStart(2, '0');
// Local timestamp 'YYYY-MM-DD HH:MM:SS' (same format the API has always returned)
function nowStamp(d = new Date()) {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

// Escape user text before using it in a $regex
const rx = (s) => new RegExp(String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');

/* ---------- settings ---------- */
async function getSetting(key, fallback = null) {
  const r = await col('settings').findOne({ _id: key });
  return r ? r.value : fallback;
}
async function setSetting(key, value) {
  await col('settings').updateOne({ _id: key }, { $set: { value } }, { upsert: true });
}

module.exports = {
  connect, close, db, col, COLLECTIONS, ensureIndexes,
  nextSeq, nextId, insert, out, toId, nowStamp, rx,
  getSetting, setSetting, DATA_DIR, MONGODB_URI, DB_NAME, safeUri,
};
